-- Knitwright core schema (Postgres 16). Starting point for migrations; see 03-data-model.md.
-- Money in integer minor units + currency. Lengths in millimetres. IDs are UUIDv7 generated by the app.

create type workspace_kind as enum ('club', 'brand');
create type member_role as enum ('admin', 'manager', 'viewer');
create type production_class as enum ('A', 'B');
create type version_status as enum ('draft', 'validated', 'approved', 'ordered');
create type provenance as enum ('observed', 'inferred', 'unknown', 'user_confirmed');
create type order_source as enum ('teamwear', 'team_store', 'storefront', 'shopify', 'sample', 'run');
create type order_status as enum ('pending_payment', 'paid', 'in_batch', 'at_factory', 'in_production',
                                  'qc_passed', 'qc_failed', 'shipped', 'delivered', 'cancelled', 'refunded');
create type batch_status as enum ('open', 'cut_off', 'sent', 'in_production', 'ready_for_qc', 'qc_done', 'shipped');
create type moderation_result as enum ('pending', 'clear', 'flagged', 'blocked');

create table app_user (
  id uuid primary key,
  email text unique not null,
  name text,
  created_at timestamptz not null default now()
);

create table workspace (
  id uuid primary key,
  kind workspace_kind not null,
  name text not null,
  slug text unique not null,
  country char(2) not null,
  custom_domain text unique,
  plan text not null default 'free',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table membership (
  workspace_id uuid references workspace(id),
  user_id uuid references app_user(id),
  role member_role not null,
  primary key (workspace_id, user_id)
);

create table file_artifact (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  kind text not null,                -- crest, sponsor, upload, print_file, dxf, techpack_pdf, media_image, ...
  r2_key text not null,
  sha256 char(64) not null,
  bytes bigint not null,
  mime text not null,
  generated_from_version_hash text,
  created_at timestamptz not null default now()
);

-- Catalogue -------------------------------------------------------------

create table fabric (
  id uuid primary key,
  code text unique not null,
  blend text not null,
  gsm int not null,
  stretch text,
  finish text,
  sublimatable boolean not null,
  pfas_free boolean not null default true,
  oeko_tex_cert text,
  swatch_ref text
);

create table fabric_colour (
  id uuid primary key,
  fabric_id uuid references fabric(id),
  name text not null,
  hex char(7) not null,
  lab numeric[] not null,
  pantone text
);

create table base_article (
  id uuid primary key,
  code text unique not null,
  name text not null,
  class production_class not null,
  sport_tags text[] not null default '{}',
  hs_code text not null,
  glb_model_key text not null,
  uv_panel_map jsonb not null,           -- panel_id -> uv rect + print box mm (size M)
  size_range text[] not null,
  pom_table jsonb not null,              -- {size: {pom_code: {value_mm, tol_mm}}}
  parametric_script text not null,       -- module id@version
  active boolean not null default false
);

create table parameter_def (
  id uuid primary key,
  article_id uuid references base_article(id),
  key text not null,
  type text not null check (type in ('range', 'enum', 'bool')),
  min numeric, max numeric, step numeric,
  enum_values text[],
  default_value jsonb not null,
  affects_panels text[] not null,
  approved_by_golden_sample_id uuid,
  unique (article_id, key)
);

create table option_def (
  id uuid primary key,
  article_id uuid references base_article(id),
  option_group text not null,            -- collar, sleeve, pocket
  value text not null,
  thumbnail_key text,
  extra_cost_minor int not null default 0,
  unique (article_id, option_group, value)
);

create table panel_geometry (
  article_id uuid references base_article(id),
  size text not null,
  panel_id text not null,
  outline jsonb not null,                -- closed polyline in mm
  seam_allowance_mm numeric not null,
  notches jsonb not null,
  grainline jsonb not null,
  print_box_mm jsonb not null,
  uv_rect jsonb not null,
  primary key (article_id, size, panel_id)
);

create table factory (
  id uuid primary key,
  name text not null,
  city text not null,
  country char(2) not null,
  contact_whatsapp text,
  certifications jsonb not null default '[]', -- [{name, number, expires_at, file_artifact_id, verified_by}]
  status text not null default 'onboarding'
);

create table factory_capability (
  id uuid primary key,
  factory_id uuid references factory(id),
  article_id uuid references base_article(id),
  fabric_id uuid references fabric(id),
  lead_time_days int not null,
  moq int not null,
  weekly_slot_capacity int,              -- Class A pieces per week
  file_formats_accepted text[] not null,
  golden_sample_status text not null default 'none', -- none, submitted, approved, rejected
  colour_delta_max numeric not null default 1.5,
  active boolean not null default false,
  unique (factory_id, article_id, fabric_id)
);

create table price_tier (
  id uuid primary key,
  capability_id uuid references factory_capability(id),
  qty_min int not null,
  qty_max int,
  cost_minor int not null, cost_currency char(3) not null,
  sell_gbp_minor int, sell_aud_minor int,
  personalisation_cost_minor int not null default 0
);

create table country_rule (
  country char(2) primary key,
  selling_enabled boolean not null default false,
  vat_rate numeric,
  low_value_threshold_minor int,
  threshold_currency char(3),
  duty_by_hs jsonb not null default '{}',
  preference_scheme text,                -- e.g. UK DCTS Enhanced
  label_rules jsonb not null default '{}',
  updated_at timestamptz not null default now()
);

-- Design ------------------------------------------------------------------

create table design (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  base_article_id uuid references base_article(id),
  title text not null,
  current_version_id uuid,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table design_version (
  id uuid primary key,
  design_id uuid references design(id),
  parent_version_id uuid references design_version(id),
  doc jsonb not null,                    -- validated against design-object.schema.json
  hash char(64) not null,
  status version_status not null default 'draft',
  created_by uuid references app_user(id),
  created_at timestamptz not null default now()
);

create table validation_result (
  id uuid primary key,
  version_id uuid references design_version(id),
  factory_id uuid references factory(id),
  checks jsonb not null,                 -- [{code, severity, message, target}]
  passed boolean not null,
  created_at timestamptz not null default now()
);

create table golden_sample (
  id uuid primary key,
  version_id uuid references design_version(id),
  factory_id uuid references factory(id),
  photos uuid[] not null,
  measured_pom jsonb not null,
  delta_e jsonb not null,
  approved_by uuid references app_user(id),
  approved_at timestamptz
);

create table benchmark (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  title text not null,
  created_at timestamptz not null default now()
);

create table benchmark_item (
  id uuid primary key,
  benchmark_id uuid references benchmark(id),
  source_url text,
  source_upload_id uuid references file_artifact(id),
  fetched_at timestamptz,
  fields jsonb not null,                 -- {field: {value, provenance}}
  complaint_themes jsonb not null default '[]'
);

create table moderation_check (
  id uuid primary key,
  target_kind text not null,             -- asset, text, version
  target_id uuid not null,
  result moderation_result not null,
  reasons jsonb not null default '[]',
  reviewer_id uuid references app_user(id),
  created_at timestamptz not null default now()
);

-- Selling -----------------------------------------------------------------

create table roster (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  season text not null,
  signup_token_hash text
);

create table roster_entry (
  id uuid primary key,
  roster_id uuid references roster(id),
  name_on_shirt text,
  number int,
  size text,
  email text,
  status text not null default 'invited'
);

create table team_store (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  roster_id uuid references roster(id),
  version_ids uuid[] not null,
  opens_at timestamptz not null,
  closes_at timestamptz not null,
  min_pieces int not null default 10,
  club_margin_pct numeric not null default 0,
  delivery_mode text not null default 'one_address',
  short_code text unique not null,
  status text not null default 'draft'
);

create table storefront (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  theme jsonb not null default '{}',
  custom_domain text unique,
  status text not null default 'draft'
);

create table listing (
  id uuid primary key,
  storefront_id uuid references storefront(id),
  version_id uuid references design_version(id),
  mode text not null check (mode in ('drop', 'mto', 'stocked')),
  retail_minor int not null, currency char(3) not null,
  drop_opens_at timestamptz, drop_closes_at timestamptz, target_qty int,
  shopify_product_id text,
  status text not null default 'draft'
);

create table customer_order (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  source order_source not null,
  team_store_id uuid references team_store(id),
  listing_id uuid references listing(id),
  buyer_email text not null,
  ship_to jsonb not null,
  country char(2) not null,
  total_minor int not null, currency char(3) not null,
  vat_minor int not null default 0,
  status order_status not null default 'pending_payment',
  promised_date date,
  created_at timestamptz not null default now()
);

create table order_line (
  id uuid primary key,
  order_id uuid references customer_order(id),
  version_id uuid references design_version(id),
  size text not null,
  qty int not null check (qty > 0),
  unit_sell_minor int not null,
  unit_cost_snapshot_minor int not null,
  cost_currency char(3) not null
);

create table personalisation (
  order_line_id uuid references order_line(id),
  seq int not null,
  name_on_shirt text,
  number int,
  roster_entry_id uuid references roster_entry(id),
  primary key (order_line_id, seq)
);

-- Operations --------------------------------------------------------------

create table batch (
  id uuid primary key,
  code text unique not null,             -- e.g. B-2026-48-A-F01
  factory_id uuid references factory(id),
  class production_class not null,
  cutoff_at timestamptz not null,
  due_at date,
  status batch_status not null default 'open'
);

create table batch_line (
  batch_id uuid references batch(id),
  order_line_id uuid references order_line(id),
  primary key (batch_id, order_line_id)
);

create table job_packet (
  id uuid primary key,
  batch_id uuid references batch(id),
  token_hash text not null,
  expires_at timestamptz not null,
  revoked boolean not null default false
);

create table factory_event (
  id uuid primary key,
  batch_id uuid references batch(id),
  type text not null,                    -- received, in_production, ready_for_qc, note, delay
  note text,
  photo_ids uuid[] not null default '{}',
  at timestamptz not null default now()
);

create table qc_record (
  id uuid primary key,
  batch_id uuid references batch(id),
  order_id uuid references customer_order(id),
  aql_level text,
  sample_size int,
  defects_major int not null default 0,
  defects_minor int not null default 0,
  passed boolean,
  photo_ids uuid[] not null default '{}',
  inspector uuid references app_user(id),
  at timestamptz not null default now()
);

create table qc_measurement (
  qc_record_id uuid references qc_record(id),
  piece_seq int not null,
  size text not null,
  pom_code text not null,
  measured_mm numeric not null,
  target_mm numeric not null,
  tolerance_mm numeric not null,
  pass boolean not null,
  primary key (qc_record_id, piece_seq, pom_code)
);

create table shipment (
  id uuid primary key,
  batch_id uuid references batch(id),
  carrier text not null,
  tracking text,
  invoice_id uuid references file_artifact(id),
  origin_proof_id uuid references file_artifact(id),
  weight_kg numeric,
  status text not null default 'booked'
);

create table package_export (
  id uuid primary key,
  version_id uuid references design_version(id),
  factory_id uuid references factory(id),
  manifest jsonb not null,
  zip_id uuid references file_artifact(id),
  paid boolean not null default false,
  created_at timestamptz not null default now()
);

create table media_set (
  id uuid primary key,
  version_id uuid references design_version(id),
  items jsonb not null,                  -- [{kind, file_artifact_id, ai_generated, model, checker_score}]
  credits_spent int not null default 0
);

create table payment (
  id uuid primary key,
  order_id uuid references customer_order(id),
  stripe_payment_intent text unique,
  amount_minor int not null, currency char(3) not null,
  status text not null
);

create table payout (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  stripe_transfer_id text unique,
  amount_minor int not null, currency char(3) not null,
  order_line_ids uuid[] not null,
  status text not null
);

-- Inspiration, product intelligence, shoots ------------------------------

create table moodboard (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  design_id uuid references design(id),
  title text not null
);

create table inspiration_item (
  id uuid primary key,
  moodboard_id uuid references moodboard(id),
  source text not null check (source in ('library', 'pinterest', 'unsplash', 'pexels', 'link_preview', 'user_upload', 'ai_mood')),
  source_url text,
  preview_url text,                      -- hotlinked per source terms; not copied to R2 unless user_upload/ai_mood/library
  file_artifact_id uuid references file_artifact(id),
  attribution text,
  tags text[] not null default '{}',
  created_at timestamptz not null default now()
);

create table pinterest_connection (
  user_id uuid primary key references app_user(id),
  access_token_enc bytea not null,
  refresh_token_enc bytea,
  scopes text[] not null,
  board_ids text[] not null default '{}',
  expires_at timestamptz
);

create table suggestion (
  id uuid primary key,
  version_id uuid references design_version(id),
  from_inspiration_id uuid references inspiration_item(id),
  design_patch jsonb not null,           -- RFC 6902 JSON Patch limited to allowed paths
  explanation text not null,
  rule_ids text[] not null default '{}',
  validated boolean not null default false,
  applied_version_id uuid references design_version(id),
  created_at timestamptz not null default now()
);

create table rulebook_entry (
  rule_id text not null,                 -- e.g. R-SUB-004
  version int not null,
  topic text not null check (topic in ('construction', 'fabric', 'print', 'fit', 'labels', 'cost', 'compliance')),
  article_codes text[] not null default '{}',
  title text not null,
  body text not null,
  best_practice text,
  source text not null,                  -- factory, pattern_master, standard, regulation
  approved_by uuid references app_user(id),
  approved_at timestamptz,
  primary key (rule_id, version)
);

create table techpack_field (
  version_id uuid references design_version(id),
  section text not null,                 -- overview, construction, bom, pom, graphics, labels, colourway
  key text not null,
  value jsonb,
  provenance text not null check (provenance in ('from_base', 'from_design', 'needs_input', 'confirmed')),
  rule_id text,
  primary key (version_id, section, key)
);

create table shoot_concept (
  id uuid primary key,
  name text not null,
  sports text[] not null default '{}',
  article_codes text[] not null default '{}',
  scene jsonb not null,
  lighting jsonb not null,
  camera jsonb not null,
  output_set jsonb not null,
  active boolean not null default true
);

create table shoot_pose (
  id uuid primary key,
  concept_id uuid references shoot_concept(id),
  name text not null,
  reference_key text not null
);

create table model_preset (
  id uuid primary key,
  label text not null,
  attributes jsonb not null,
  licence_ref text not null              -- AI-generated, licensed; no real people
);

create table shoot_job (
  id uuid primary key,
  version_id uuid references design_version(id),
  concept_id uuid references shoot_concept(id),
  garment_source text not null check (garment_source in ('render', 'golden_sample_photo')),
  model_preset_id uuid references model_preset(id),
  model_upload_id uuid references file_artifact(id),
  consent_confirmed boolean not null default false,
  background jsonb,
  pose_id uuid references shoot_pose(id),
  media_set_id uuid references media_set(id),
  checker_scores jsonb not null default '[]',
  credits int not null default 0,
  status text not null default 'queued',
  created_at timestamptz not null default now(),
  check (model_upload_id is null or consent_confirmed)
);

-- Brand Studio, templates, launch canvas and Flows, collection plans, credits ------

create table brand (
  workspace_id uuid primary key references workspace(id),
  name text not null,
  category text,                         -- club, sportswear_brand, gym, esports_team, school
  website text,
  about text check (char_length(about) <= 1000),
  palettes jsonb not null default '[]',  -- [{name, colours:[{name, hex, pantone, sublimation_safe_hex}]}]
  fonts jsonb not null default '{}',     -- {headline:{font,weight}, subheadline, body, accent, name_number}
  logos uuid[] not null default '{}',
  graphics uuid[] not null default '{}',
  visual_style jsonb,                    -- {setting, art_direction, rules}
  voice_tags text[] not null default '{}',
  completion_pct int not null default 0,
  imported_from_url text,
  updated_at timestamptz not null default now()
);

create table template (
  id uuid primary key,
  kind text not null check (kind in ('design', 'kit_bundle', 'mockup_scene', 'marketing', 'video', 'flow', 'techpack')),
  name text not null,
  sport_tags text[] not null default '{}',
  article_codes text[] not null default '{}',
  style_tags text[] not null default '{}',
  mood text,
  colour_family text,
  payload jsonb not null,
  thumbnail_key text,
  status text not null default 'draft',  -- draft, live, retired
  likes int not null default 0,
  uses int not null default 0
);

create table project (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  name text not null,
  units text not null default 'px' check (units in ('px', 'in', 'mm')),
  from_template_id uuid references template(id),
  created_at timestamptz not null default now()
);

create table board (
  id uuid primary key,
  project_id uuid references project(id),
  kind text not null check (kind in ('design', 'artboard', 'mockup', 'ai_image', 'ai_video', 'marketing', 'info_card', 'note', 'section_label')),
  name text,
  position jsonb not null,               -- {x, y}
  size jsonb not null,                   -- {w, h, unit}
  settings jsonb not null default '{}',  -- prompt, model, aspect, style, duration_s, preset, audio, colourway, roster_entry
  input_version_id uuid references design_version(id),
  output_artifact_id uuid references file_artifact(id),
  status text not null default 'idle',   -- idle, queued, generating, done, failed, checker_rejected
  last_cost int not null default 0
);

create table board_edge (
  from_board_id uuid references board(id),
  to_board_id uuid references board(id),
  input_index int not null default 1,    -- "image 1", "image 2"
  primary key (from_board_id, to_board_id)
);

create table flow_run (
  id uuid primary key,
  project_id uuid references project(id),
  board_ids uuid[] not null,
  estimated_credits int not null,
  spent_credits int not null default 0,
  refunded_credits int not null default 0,
  status text not null default 'queued',
  results jsonb not null default '[]',
  created_at timestamptz not null default now()
);

create table collection_plan (
  id uuid primary key,
  workspace_id uuid references workspace(id),
  name text not null,
  season text
);

create table plan_group (
  id uuid primary key,
  plan_id uuid references collection_plan(id),
  name text not null,
  frame jsonb not null
);

create table plan_style (
  id uuid primary key,
  plan_id uuid references collection_plan(id),
  group_id uuid references plan_group(id),
  design_id uuid references design(id),
  colourways text[] not null default '{}',
  sizes text[] not null default '{}',
  qty int,
  split_wholesale_pct numeric not null default 0,
  wholesale_minor int,
  rrp_minor int,
  currency char(3) not null default 'GBP',
  status text not null default 'draft'   -- draft, sampling, approved, ordered
);

create table credit_ledger (
  id bigserial primary key,
  workspace_id uuid references workspace(id),
  delta int not null,
  reason text not null,                  -- plan_grant, top_up, generation, refund
  ref_kind text,
  ref_id uuid,
  at timestamptz not null default now()
);

create table audit_log (
  id bigserial primary key,
  actor uuid,
  entity text not null,
  entity_id uuid not null,
  before jsonb,
  after jsonb,
  at timestamptz not null default now()
);
